# -*- coding: utf-8 -*-
from _lib import *
MM='Manuel des Monstres 5e (2014)'
I(1,'Dans D&D 5e, lequel de ces fiélons est un démon (et non un diable) ?','Balor',['Diable barbu','Diable à chaînes','Diablotin'],'Le balor vient des Abysses : c’est un démon. Les trois autres sont des diables des Neuf Enfers.',MM+', entrées « Balor », « Diable barbu », « Diable à chaînes », « Diablotin »')
I(2,'Dans D&D 5e, lequel de ces fiélons n’est pas un Seigneur démon des Abysses ?','Asmodeus',['Demogorgon','Orcus','Yeenoghu'],'Asmodeus est le maître des Neuf Enfers (un archidiable). Demogorgon, Orcus et Yeenoghu sont des Seigneurs démons.',MM+' et Mordenkainen Presents: Monsters of the Multiverse (2022)')
I(3,'Dans D&D 5e, lequel de ces fiélons est un diable parmi des démons ?','Érinye',['Vrock','Hezrou','Glabrezu'],'L’érinye est un diable des Neuf Enfers. Vrock, hezrou et glabrezu sont des démons des Abysses.',MM+', entrées correspondantes')
T(1,'Dans D&D 5e, les tieffelins descendent d’humains qui ont conclu un pacte avec des ____.','fiélons',['dragons','fées','géants'],'Les tieffelins portent la marque d’une ascendance infernale : leurs ancêtres ont fait un pacte avec des fiélons.',"Manuel des Joueurs 5e (2014), chapitre « Races »")
T(2,'Dans D&D 5e, le succube peut changer de forme pour ____ ses victimes.','charmer',['pétrifier','paralyser','aveugler'],'Le succube (ou l’incube) peut charmer un humanoïde ; son baiser draine ensuite l’énergie vitale.',MM+', entrée « Succube / Incube »')
T(1,'Dans D&D 5e, les diables vivent dans les ____ Enfers, dirigés par Asmodeus.','Neuf',['Sept','Douze','Treize'],'Les Neuf Enfers sont le plan des diables, gouverné par Asmodeus.',"Dungeon Master’s Guide 5e (2014), chapitre « Les plans »")
M(2,'Dans D&D 5e, lesquels de ces fiélons sont des démons ? (plusieurs bonnes réponses)',['Vrock','Hezrou','Balor'],['Diablotin','Diable barbu'],'Vrock, hezrou et balor sont des démons ; le diablotin et le diable barbu sont des diables.',MM+', entrées correspondantes')
M(2,'Dans D&D 5e, lesquels de ces personnages sont des Seigneurs démons ? (plusieurs bonnes réponses)',['Demogorgon','Orcus','Yeenoghu'],['Asmodeus','Méphistophélès'],'Asmodeus et Méphistophélès sont des archidiables ; les trois autres règnent sur les Abysses.',MM+' et Monsters of the Multiverse (2022)')
M(3,'Dans D&D 5e, lesquelles de ces couches font partie des Neuf Enfers ? (plusieurs bonnes réponses)',['Avernus','Dis','Cania'],['Carcéri','Pandémonium'],'Avernus, Dis et Cania sont des couches des Neuf Enfers. Carcéri et Pandémonium sont d’autres plans extérieurs.',"Dungeon Master’s Guide 5e (2014), chapitre « Les plans »")
O(3,'Classe ces fiélons par FP croissant (du moins dangereux au plus dangereux).',['Diablotin','Diable barbu','Hezrou','Balor','Pit fiend'],'FP : diablotin 1, diable barbu 3, hezrou 8, balor 19, pit fiend 20.',MM+', blocs de caractéristiques')
O(3,'Classe ces couches des Neuf Enfers de la première à la dernière.',['Avernus','Dis','Stygia','Cania','Nessus'],'Ordre des couches : Avernus (1re), Dis (2e), Minauros, Phlégéthos, Stygia (5e), Malbolge, Maladomini, Cania (8e), Nessus (9e).',"Dungeon Master’s Guide 5e (2014), chapitre « Les plans »")
A(2,'Associe chaque démon à son apparence.',[('Vrock','Vautour humanoïde'),('Hezrou','Crapaud géant'),('Marilith','Six bras, queue de serpent'),('Nalfeshnee','Tête de sanglier')],'Chaque démon majeur a une forme reconnaissable : vautour, crapaud, femme-serpent à six bras, sanglier.',MM+', entrées correspondantes')
A(2,'Associe chaque Seigneur démon à son domaine.',[('Demogorgon','Prince des Démons'),('Yeenoghu','Gnolls'),('Baphomet','Minotaures'),('Zuggtmoy','Champignons')],'Chaque Seigneur démon règne sur un thème : le Prince des Démons, les gnolls, les minotaures, les champignons.','Mordenkainen Presents: Monsters of the Multiverse (2022)')
W(1,['Je suis minuscule, ailé et cruel.','Je suis un diable de rang inférieur.','On me trouve souvent comme familier d’un sorcier.'],'Diablotin',['Quasit','Succube','Gargouille'],'Le diablotin est un petit diable malfaisant qui sert souvent de familier.',MM+', entrée « Diablotin »')
W(2,['Je suis un démon de grande taille, ailé et enflammé.','Je manie une épée de foudre et un fouet de flammes.','Quand je meurs, j’explose violemment.'],'Balor',['Pit fiend','Marilith','Nalfeshnee'],'Le balor est un démon colossal ; sa mort provoque une explosion.',MM+', entrée « Balor »')
W(3,['Je suis un fiélon capable de prendre l’apparence d’un humanoïde séduisant.','Je cache mes ailes quand je veux tromper mes proies.','Mon baiser draine l’énergie vitale.'],'Succube',['Érinye','Quasit','Hezrou'],'Le succube séduit et draine la vie par son baiser.',MM+', entrée « Succube / Incube »')
save('demons-diables-dnd','dem')
